261	  public isDependencyTreeDurable(lookupRegistry: string[] = []): boolean {
262	    if (!isUndefined(this.isTreeDurable)) {
263	      return this.isTreeDurable;
264	    }
265	    if (this.scope === Scope.REQUEST) {
266	      this.isTreeDurable = this.durable === undefined ? false : this.durable;
267	      if (this.isTreeDurable) {
268	        this.printIntrospectedAsDurable();
269	      }
270	      return this.isTreeDurable;
271	    }
272	    const isStatic = this.isDependencyTreeStatic();
273	    if (isStatic) {
274	      return false;
275	    }
276	
277	    const isTreeNonDurable = this.introspectDepsAttribute(
278	      (collection, registry) =>
279	        collection.some(
280	          (item: InstanceWrapper) =>
281	            !item.isDependencyTreeStatic() &&
282	            !item.isDependencyTreeDurable(registry),
283	        ),
284	      lookupRegistry,
285	    );
286	    this.isTreeDurable = !isTreeNonDurable;
287	    if (this.isTreeDurable) {
288	      this.printIntrospectedAsDurable();
289	    }
290	    return this.isTreeDurable;
291	  }
