293	  public introspectDepsAttribute(
294	    callback: (
295	      collection: InstanceWrapper[],
296	      lookupRegistry: string[],
297	    ) => boolean,
298	    lookupRegistry: string[] = [],
299	  ): boolean {
300	    if (lookupRegistry.includes(this[INSTANCE_ID_SYMBOL])) {
301	      return false;
302	    }
303	    lookupRegistry = lookupRegistry.concat(this[INSTANCE_ID_SYMBOL]);
304	
305	    const { dependencies, properties, enhancers } =
306	      this[INSTANCE_METADATA_SYMBOL];
307	
308	    let introspectionResult = dependencies
309	      ? callback(dependencies, lookupRegistry)
310	      : false;
311	
312	    if (introspectionResult || !(properties || enhancers)) {
313	      return introspectionResult;
314	    }
315	    introspectionResult = properties
316	      ? callback(
317	          properties.map(item => item.wrapper),
318	          lookupRegistry,
319	        )
320	      : false;
321	    if (introspectionResult || !enhancers) {
322	      return introspectionResult;
323	    }
324	    return enhancers ? callback(enhancers, lookupRegistry) : false;
325	  }
326	
327	  public isDependencyTreeStatic(lookupRegistry: string[] = []): boolean {
328	    if (!isUndefined(this.isTreeStatic)) {
329	      return this.isTreeStatic;
330	    }
331	    if (this.scope === Scope.REQUEST) {
332	      this.isTreeStatic = false;
333	      this.printIntrospectedAsRequestScoped();
334	      return this.isTreeStatic;
335	    }
336	    this.isTreeStatic = !this.introspectDepsAttribute(
337	      (collection, registry) =>
338	        collection.some(
339	          (item: InstanceWrapper) => !item.isDependencyTreeStatic(registry),
340	        ),
341	      lookupRegistry,
342	    );
343	    if (!this.isTreeStatic) {
344	      this.printIntrospectedAsRequestScoped();
345	    }
346	    return this.isTreeStatic;
347	  }
348	
349	  public cloneStaticInstance(contextId: ContextId): InstancePerContext<T> {
350	    const staticInstance = this.getInstanceByContextId(STATIC_CONTEXT);
351	    if (this.isDependencyTreeStatic()) {
352	      return staticInstance;
353	    }
354	    const instancePerContext: InstancePerContext<T> = {
355	      ...staticInstance,
356	      instance: undefined!,
357	      isResolved: false,
358	      isPending: false,
359	    };
360	    if (this.isNewable()) {
361	      instancePerContext.instance = Object.create(this.metatype!.prototype);
362	    }
363	    this.setInstanceByContextId(contextId, instancePerContext);
364	    return instancePerContext;
365	  }
366	
367	  public cloneTransientInstance(
368	    contextId: ContextId,
369	    inquirerId: string,
370	  ): InstancePerContext<T> {
371	    const staticInstance = this.getInstanceByContextId(STATIC_CONTEXT);
372	    const instancePerContext: InstancePerContext<T> = {
373	      ...staticInstance,
374	      instance: undefined!,
375	      isResolved: false,
376	      isPending: false,
377	    };
378	    if (this.isNewable()) {
379	      instancePerContext.instance = Object.create(this.metatype!.prototype);
380	    }
381	    this.setInstanceByInquirerId(contextId, inquirerId, instancePerContext);
382	    return instancePerContext;
383	  }
384	
385	  public createPrototype(contextId: ContextId) {
386	    const host = this.getInstanceByContextId(contextId);
387	    if (!this.isNewable() || host.isResolved) {
388	      return;
389	    }
390	    return Object.create(this.metatype!.prototype);
391	  }
392	
393	  public isInRequestScope(
394	    contextId: ContextId,
395	    inquirer?: InstanceWrapper,
396	  ): boolean {
397	    const isDependencyTreeStatic = this.isDependencyTreeStatic();
398	
399	    return (
400	      !isDependencyTreeStatic &&
401	      contextId !== STATIC_CONTEXT &&
402	      (!this.isTransient || (this.isTransient && !!inquirer))
403	    );
404	  }
405	
406	  public isLazyTransient(
407	    contextId: ContextId,
408	    inquirer: InstanceWrapper | undefined,
409	  ): boolean {
410	    const isInquirerRequestScoped = !!(
411	      inquirer && !inquirer.isDependencyTreeStatic()
412	    );
413	
414	    return (
415	      this.isDependencyTreeStatic() &&
416	      contextId !== STATIC_CONTEXT &&
417	      this.isTransient &&
418	      isInquirerRequestScoped
419	    );
420	  }
421	
422	  public isExplicitlyRequested(
423	    contextId: ContextId,
424	    inquirer?: InstanceWrapper,
425	  ): boolean {
426	    const isSelfRequested = inquirer === this;
427	    return (
428	      this.isDependencyTreeStatic() &&
429	      contextId !== STATIC_CONTEXT &&
430	      (isSelfRequested || !!(inquirer && inquirer.scope === Scope.TRANSIENT))
431	    );
432	  }
433	
434	  public isStatic(
435	    contextId: ContextId,
436	    inquirer: InstanceWrapper | undefined,
437	  ): boolean {
438	    if (!this.isDependencyTreeStatic() || contextId !== STATIC_CONTEXT) {
439	      return false;
440	    }
441	
442	    // Non-transient provider in static context
443	    if (!this.isTransient) {
444	      return true;
445	    }
446	
447	    const isInquirerRequestScoped =
448	      inquirer && !inquirer.isDependencyTreeStatic();
