import { Logger } from '@nestjs/common';
import type { OnModuleDestroy } from '@nestjs/common';
import { isFunction, isNil } from '@nestjs/common/internal';
import { NestContainer } from '../injector/container.js';
import { ContextId, InstanceWrapper } from '../injector/instance-wrapper.js';
import { Module } from '../injector/module.js';

function hasOnModuleDestroyHook(instance: unknown): instance is OnModuleDestroy {
  return isFunction((instance as OnModuleDestroy).onModuleDestroy);
}

function forEachWrapper(moduleRef: Module, callback: (wrapper: InstanceWrapper) => void) {
  const collections = [
    moduleRef.providers,
    moduleRef.controllers,
    moduleRef.injectables,
    moduleRef.middlewares,
  ];
  for (const collection of collections) {
    collection.forEach(callback);
  }
}

export async function callContextDestroyHook(
  container: NestContainer,
  contextId: ContextId,
): Promise<void> {
