/**
 * Tracks the instances created for a single non-static DI context
 * (e.g. one HTTP request) so their `onModuleDestroy` hooks can be invoked
 * when the application shuts down. Trackers are expected to be released
 * (dropped) once the owning context settles.
 */
export class ScopedContextTracker {
  private readonly hosts = new Set<InstancePerContext<unknown>>();

  public add(host: InstancePerContext<unknown>): void {
    this.hosts.add(host);
  }

  /**
   * Returns the instances that are still alive and have been fully
   * constructed, and detaches them from the tracker so subsequent
   * enumerations (or shutdown cycles) never see them again.
   */
  public drainInstances(): unknown[] {
    const instances: unknown[] = [];
    for (const host of this.hosts) {
      this.hosts.delete(host);
      const instance = host.instance;
      if (host.isConstructorCalled && !isNil(instance) && hasOnModuleDestroyHook(instance)) {
        instances.push(instance);
      }
    }
    return instances;
  }
}
