export class ScopedInstancesRegistry {
  private static readonly logger = new Logger(ScopedInstancesRegistry.name);
  private readonly trackers = new WeakMap<ContextId, ScopedContextTracker>();

  public track(
    contextId: ContextId,
    wrapper: InstanceWrapper,
    host: InstancePerContext<unknown>,
  ): void {
    let tracker = this.trackers.get(contextId);
    if (!tracker) {
      tracker = new ScopedContextTracker();
      this.trackers.set(contextId, tracker);
    }
    tracker.add(host);
  }

  /**
   * Detaches the tracker bound to the given context, e.g. when the
   * underlying request has been fully processed.
   */
  public release(contextId: ContextId): void {
    this.trackers.delete(contextId);
