import { Logger } from '@nestjs/common';
import type { OnModuleDestroy } from '@nestjs/common';
import { isFunction, isNil } from '@nestjs/common/internal';
import type { ContextId, InstancePerContext } from './instance-wrapper.js';
import type { InstanceWrapper } from './instance-wrapper.js';

/**
 * Key that identifies a scoped instance within a context: the wrapper that
 * created it plus the inquirer (for transient providers).
 */
export interface ScopedInstanceKey {
  wrapperId: string;
  inquirerId?: string;
}

/**
 * Tracks instances created for a single non-static DI context (for example
 * one HTTP request) so their `onModuleDestroy` hooks can be invoked when the
 * application shuts down. The hook for each tracked instance is invoked at
 * most once, even if the registry is closed multiple times or the same
 * instance is registered more than once.
 */
export class ScopedContextTracker {
  private readonly instances = new Map<string, InstancePerContext<unknown>>();
  private closed = false;

  /**
   * Registers an instance created within this context. The `key` must be
   * unique per `InstanceWrapper` and (for transient providers) per inquirer.
   */
  public register(
    key: ScopedInstanceKey,
    instancePerContext: InstancePerContext<unknown>,
  ): void {
    if (this.closed) {
      return;
    }
    this.instances.set(this.keyToString(key), instancePerContext);
  }

  /**
   * Invokes `onModuleDestroy` on every tracked instance that has been fully
   * constructed and has such a hook, then clears the tracker. Subsequent
   * calls have no effect.
   */
  public async destroy(): Promise<void> {
    if (this.closed) {
      return;
    }
    this.closed = true;
    const instances = [...this.instances.values()];
    this.instances.clear();
    await Promise.all(
      instances
        .filter(
          (instancePerContext): instancePerContext is InstancePerContext<unknown> & { instance: unknown } =>
            !isNil(instancePerContext.instance) &&
            instancePerContext.isConstructorCalled === true &&
            isFunction((instancePerContext.instance as OnModuleDestroy).onModuleDestroy),
        )
        .map(async (instancePerContext) => {
          try {
            await (instancePerContext.instance as OnModuleDestroy).onModuleDestroy();
          } catch (error) {
            Logger.error(
              (error as Error)?.stack ?? String(error),
              'ScopedContextTracker',
            );
          }
        }),
    );
  }

  private keyToString(key: ScopedInstanceKey): string {
    return key.inquirerId ? `${key.wrapperId}:${key.inquirerId}` : key.wrapperGlobalKey;
  }
}

